  PURE.hopOver = hopOver;
  PURE.hopBare = hopBare;
  PURE.focusInkKey = focusInkKey;
  PURE.nightCosDefault = nightCosDefault;
  PURE.PHONE_PANEL_MIN = PHONE_PANEL_MIN;
  PURE.PHONE_RAIL_MIN = PHONE_RAIL_MIN;
  PURE.DISC_BAND_PAD = DISC_BAND_PAD;
  PURE.VIEW_BIAS_MIN_PANEL = VIEW_BIAS_MIN_PANEL;
  /* r19r: the two measured constants this round's laws are written against */
  PURE.RAIL_BAND_REM = RAIL_BAND_REM;
  PURE.HOP_STILL_MS = HOP_STILL_MS;
  PURE.HOP_ETA_RE = HOP_ETA_RE;
