    syncRailCue();
    /* r19r (5): and every chip is told whether the plate is showing it */
    syncQueueReach();
    /* r19p (10): and the camera is told which band of the screen is still the
       reader's, now that the sheet has been placed */
    syncViewBias(v, railRect);
