      g.beginPath(); g.arc(11, 7.5, 2, 0, Math.PI * 2); g.stroke();
      g.lineWidth = 1;
      g.save(); g.globalAlpha *= 0.55;
      g.beginPath(); g.arc(11, 7.5, 5, 0, Math.PI * 2); g.stroke();
      g.restore();
