  /* a canvas gesture must not leave a panel button focused, or Space re-fires
     the last thing clicked (site sweep A2) */
  function blurPanelControl() {
    var a = document.activeElement;
    if (!a || a === document.body || a === el.canvas) return;
    if (el.panel && el.panel.contains(a) && a.blur) { try { a.blur(); } catch (e) {} }
  }

  /* ======================================================================
     14. Clocks
     ====================================================================== */

  /* The page's clock. The kernel owns feed timing; this is what drives the
     director's tick, the stopwatch tile count-up and the ripple phase, so a
     test can fast-forward the narration without touching the network timers
     (window.__obs.mockNow). Zero offset is the normal path. */
  function nowMs() {
    var core = CORE();
    var t = (core && typeof core.now === 'function') ? core.now() : Date.now();
    return t + ((st && st.clockOffset) || 0);   /* headless callers may run before st exists */
  }
  function perfNow() {
    return (global.performance && global.performance.now) ? global.performance.now() : Date.now();
  }

  /* ======================================================================
     15. Boot
     ====================================================================== */

