    el.apToggle = document.getElementById('obs-ap-toggle');
    el.apLabel = document.getElementById('obs-ap-label');
    el.apPill = document.getElementById('obs-ap-pill');   /* r25 (8) */
    el.apPillHead = document.getElementById('obs-ap-pill-head');   /* r26 (16) */
    el.legend = document.getElementById('obs-legend');
    el.eventCard = document.getElementById('obs-event-card');
